#!/usr/bin/env python3
"""Resume the exact saved original 169-record Archivematica receiving operation."""
import ast, base64, hashlib, json, os, stat, sys, zipfile
from pathlib import Path

ARCHIVE = Path("/workspace/scratch/6ba15c52ace4/archivematica-checkpoint-input/Archivematica_Interrupted_Checkpoint_73b6c816b0983b31.zip")
ARCHIVE_BYTES = 18228351
ARCHIVE_SHA = "eb23c0d4f7c7d6ec3c6fe9d5148bd4aab7107f0c7bee93b6c609c26ae4865441"
OP = "ARCHIVEMATICA-RESEARCH-RECEIVING-6BA15-20261012"
OVERLAY = json.loads(base64.b64decode("", validate=True))

def need(value, message):
    if not value:
        raise RuntimeError(message)

def sha(raw):
    return hashlib.sha256(raw).hexdigest()

def main():
    fd = os.open(ARCHIVE, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
    with os.fdopen(fd, "rb") as stream:
        before = os.fstat(stream.fileno())
        need(stat.S_ISREG(before.st_mode), "Select the original regular saved checkpoint")
        digest, length = hashlib.sha256(), 0
        for block in iter(lambda: stream.read(262144), b""):
            digest.update(block)
            length += len(block)
        need(length == ARCHIVE_BYTES and digest.hexdigest() == ARCHIVE_SHA,
             "The placed original checkpoint bytes changed")
        stream.seek(0)
        with zipfile.ZipFile(stream) as archive:
            names = archive.namelist()
            need(len(names) == len(set(names)), "Duplicate original checkpoint member")
            manifest_raw = archive.read("DELIVERY_MEMBERS.json")
            need(len(manifest_raw) == 1222967 and sha(manifest_raw) ==
                 "2136387e9782a51c01409bea17831139f5c5febcf272b805776aa05f51036899",
                 "The original checkpoint manifest changed")
            manifest = json.loads(manifest_raw)
            need(manifest["operationId"] == OP and set(names) == set(manifest["files"]) | {"DELIVERY_MEMBERS.json"},
                 "The original checkpoint inventory belongs to another operation")
            def read(name, count=None, digest=None):
                raw = archive.read(name)
                need(manifest["files"].get(name) == {"bytes": len(raw), "sha256": sha(raw)},
                     "A retained source member changed: " + name)
                need(count is None or len(raw) == count, "A source member length changed: " + name)
                need(digest is None or sha(raw) == digest, "A source member identity changed: " + name)
                return raw.decode("utf-8")
            program = read("complete_archivematica_delivery.py", 73447,
                           "d9e309ce7434ff533e8967133b9ee0fe87947fd2117dd11490c561733490f15a")
            packet_text = read("source-input.json", 1563036,
                               "3eca3c297fb928bb772dc3b45f694bfe2b059d3579c1a41894dc9fe419d9fac9")
            caller = read("library_upload_private_state.py", 4034,
                          "d1047f61b8c6b6b3a7f24a2d1fffe4b68e6407aa146f034b18beab3824bfb39e")
            history = read("native-receiving/receiving-source/prior-attempts/native-session-12007/FAILED_ATTEMPT.json",
                           28659, "5eb34cc04b075bf4cd488466169668a434be2bd363f161211fdfab1b7eb1a1b9")
            runner = read("receiving/run-archivematica-receiving.py", 137680,
                          "743de87d3b40e41a2e30d2b8b41d1efa3221127bd4cbc38bf498bb912a388965")
        after = os.fstat(stream.fileno())
        identity = lambda item: (item.st_dev, item.st_ino, item.st_size, item.st_mtime_ns, item.st_ctime_ns)
        need(identity(before) == identity(after), "The held original checkpoint changed during source reading")
    for old, new in OVERLAY["programReplacements"]:
        need(program.count(old) == 1, "A retained wrapper source preimage is not unique")
        program = program.replace(old, new, 1)
    need(len(program.encode()) == 81166 and sha(program.encode()) ==
         "0d4146b9e044513a87c14138cbae60c45814b29375ddd2e5c27dc5bf8e46ee9c",
         "The exact same-operation wrapper successor differs")
    start = runner.index("def process_identity(pid=None):")
    end = runner.index("\nclass Fixture:", start)
    runner = runner[:start] + OVERLAY["processReplacement"] + runner[end:]
    need(runner.count(OVERLAY["gateBefore"]) == 1, "The original child START source preimage differs")
    runner = runner.replace(OVERLAY["gateBefore"], OVERLAY["gateAfter"], 1)
    need(len(runner.encode()) == 142667 and sha(runner.encode()) ==
         "2ea6c17ed1700a494abcd4014c27e4781e3abc2d19a898c18da7d7522bd20d30",
         "The reviewed namespace-aware runner differs")
    ast.parse(program, filename="complete_archivematica_delivery.py")
    ast.parse(runner, filename="run-archivematica-receiving.py")
    saved = OVERLAY["savedReceipt"]
    need(len(saved.encode()) == 1480 and sha(saved.encode()) ==
         "9536430714ff91aefdc7f15ee7d848f74643e56cacccd649446560f341b6240c",
         "The original successful checkpoint save receipt changed")
    payload = {
        "program": program, "sourcePacket": packet_text,
        "sourcePacketSha256": sha(packet_text.encode()), "caller": caller,
        "priorAttemptHistory": history, "priorAttemptHistorySha256": sha(history.encode()),
        "restoreCheckpoint": {
            "path": str(ARCHIVE), "bytes": ARCHIVE_BYTES, "sha256": ARCHIVE_SHA,
            "savedReceipt": {"encoding": "utf-8", "content": saved,
                             "bytes": len(saved.encode()), "sha256": sha(saved.encode())}},
        "runnerSuccessor": {
            "gitBlob": "9b5bd814befaa0481818fea2ddbd13b8d327b1ca",
            "originalBytes": 137680,
            "originalSha256": "743de87d3b40e41a2e30d2b8b41d1efa3221127bd4cbc38bf498bb912a388965",
            "bytes": len(runner.encode()), "sha256": sha(runner.encode()), "content": runner},
        "checkpointDiagnosis": OVERLAY["diagnosis"],
        "checkpointDiagnosisSha256": sha(OVERLAY["diagnosis"].encode())}
    print(json.dumps({"event": "ORIGINAL_CHECKPOINT_CONTINUATION_SOURCE_READY",
                      "operationId": OP, "archiveSha256": ARCHIVE_SHA,
                      "sourceCommit": json.loads(packet_text)["sourceCommit"],
                      "runnerSuccessorCommit": "ffe990f46a6b2ef405abb47f7adf6a452314e23a",
                      "runnerSha256": payload["runnerSuccessor"]["sha256"],
                      "pythonAst": "PASS", "providerReplay": False}), flush=True)
    exec(compile(program, "complete_archivematica_delivery.py", "exec"),
         {"__name__": "__main__", "PAYLOAD": payload})

if __name__ == "__main__":
    main()
